#Requires -Version 5.1
[CmdletBinding()]
param(
  [string]$SetupPath='artifacts/setup/standalone/AutoCardSync-Setup-1.0.1.exe',
  [string]$MsiPath='artifacts/installer/standalone/AutoCardSync-Standalone.msi',
  [string]$RuntimeMetadataPath='eng/installer/dotnet-desktop-runtime-10.0.10-win-x64.json',
  [string]$WebView2MetadataPath='eng/installer/webview2-evergreen-standalone-x64.json',
  [ValidatePattern('^\d+\.\d+\.\d+\.\d+$')][string]$ProductVersion='1.0.0.1',
  [ValidatePattern('^\d+\.\d+\.\d+$')][string]$SetupVersion='1.0.1',
  [string]$EvidencePath='artifacts/verification/standalone-setup-static-latest.json',
  [switch]$AllowSigned
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$verifyRoot=[IO.Path]::GetFullPath((Join-Path $root 'artifacts\verification'))
$bundleCode='{7D3642D8-03D7-459B-8E26-9B9C3C155B62}'
$msiCode='{B982E51A-D334-45B2-9D7E-64FCB9B0AF19}'
$wvCode='{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}'
$wvKey="SOFTWARE\Microsoft\EdgeUpdate\Clients\$wvCode"
function Resolve-InputPath([string]$x){if([IO.Path]::IsPathRooted($x)){[IO.Path]::GetFullPath($x)}else{[IO.Path]::GetFullPath((Join-Path $root $x))}}
function Under([string]$p,[string]$r){$p=[IO.Path]::GetFullPath($p);$r=[IO.Path]::GetFullPath($r).TrimEnd('\','/');$p.StartsWith($r+'\',[StringComparison]::OrdinalIgnoreCase)}
function Eq($a,$e,[string]$l){if($a-ne$e){throw "$l mismatch: expected '$e', actual '$a'."}}
function EqI([string]$a,[string]$e,[string]$l){if(-not[string]::Equals($a,$e,[StringComparison]::OrdinalIgnoreCase)){throw "$l mismatch: expected '$e', actual '$a'."}}
function One($a,[string]$l){$x=@($a);if($x.Count-ne 1){throw "$l requires one match; found $($x.Count)."};$x[0]}
function XML([string]$p){$x=New-Object Xml.XmlDocument;$x.Load($p);$x}
function Rows($db,[string]$sql,[int]$n){$v=$db.OpenView($sql);try{[void]$v.Execute();while($null-ne($rec=$v.Fetch())){try{$a=New-Object string[] $n;for($i=1;$i-le$n;$i++){$a[$i-1]=$rec.StringData($i)};Write-Output -NoEnumerate $a}finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($rec)}}}finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($v)}}
function HasTable($db,[string]$n){$q=[char]96;@(Rows $db "SELECT ${q}Name${q} FROM ${q}_Tables${q} WHERE ${q}Name${q} = '$n'" 1).Count-eq 1}
function Prop($db,[string]$n){$q=[char]96;$a=@(Rows $db "SELECT ${q}Value${q} FROM ${q}Property${q} WHERE ${q}Property${q} = '$n'" 1);if($a.Count-gt 1){throw "Duplicate MSI property $n."};if($a.Count){[string]$a[0][0]}else{$null}}
function LongName([string]$n){if($null-eq$n){''}else{$n.Split('|')[-1]}}
function Meta([string]$p,[string]$l){try{$m=Get-Content -LiteralPath $p -Raw -Encoding UTF8|ConvertFrom-Json}catch{throw "$l metadata JSON invalid."};foreach($n in 'schemaVersion','fileName','size','sha512','expectedSignerSubjectContains'){if($null-eq$m.PSObject.Properties[$n]){throw "$l metadata missing $n."}};Eq ([int]$m.schemaVersion) 1 "$l schema";$f=[string]$m.fileName;if([IO.Path]::GetFileName($f)-ne$f){throw "$l fileName is not a leaf."};$z=[long]$m.size;if($z-le 0){throw "$l size invalid."};$h=([string]$m.sha512).ToUpperInvariant();if($h-notmatch'^[0-9A-F]{128}$'){throw "$l SHA-512 invalid."};$sn=[string]$m.expectedSignerSubjectContains;if($sn-notmatch'Microsoft Corporation'){throw "$l signer is not Microsoft-pinned."};[pscustomobject]@{Raw=$m;File=$f;Size=$z;Hash=$h;Signer=$sn}}
function MicrosoftSig([string]$p,$m,[string]$l){$s=Get-AuthenticodeSignature -LiteralPath $p;if($s.Status-ne[Management.Automation.SignatureStatus]::Valid-or$null-eq$s.SignerCertificate){throw "$l Microsoft signature invalid: $($s.Status)."};$sub=[string]$s.SignerCertificate.Subject;if($sub.IndexOf('Microsoft Corporation',[StringComparison]::OrdinalIgnoreCase)-lt 0-or$sub.IndexOf($m.Signer,[StringComparison]::OrdinalIgnoreCase)-lt 0){throw "$l signer unexpected: $sub"};$sub}
function SafeTemp([string]$p){$p=[IO.Path]::GetFullPath($p);if(-not[string]::Equals((Split-Path -Parent $p),$verifyRoot,[StringComparison]::OrdinalIgnoreCase)-or(Split-Path -Leaf $p)-notmatch'^standalone-setup-static-[0-9a-f]{32}$'){throw "Unsafe temp path: $p"};$p}
$setup=Resolve-InputPath $SetupPath;$msi=Resolve-InputPath $MsiPath;$rmPath=Resolve-InputPath $RuntimeMetadataPath;$wmPath=Resolve-InputPath $WebView2MetadataPath;$evidence=Resolve-InputPath $EvidencePath
foreach($f in $setup,$msi,$rmPath,$wmPath){if(-not(Test-Path -LiteralPath $f -PathType Leaf)){throw "Missing input: $f"}}
if(-not(Under $evidence $verifyRoot)-or[IO.Path]::GetExtension($evidence)-ne'.json'){throw 'EvidencePath must be a JSON below artifacts/verification.'}
Eq (Split-Path -Leaf $setup) "AutoCardSync-Setup-$SetupVersion.exe" 'Setup name';Eq (Split-Path -Leaf $msi) 'AutoCardSync-Standalone.msi' 'MSI name'
$head=(& git -C $root rev-parse HEAD 2>&1|Out-String).Trim();if($LASTEXITCODE-ne 0-or$head-notmatch'^[0-9a-fA-F]{40}$'){throw 'Cannot resolve Git HEAD.'}
$rm=Meta $rmPath 'Runtime';$wm=Meta $wmPath 'WebView2';$setupHash=(Get-FileHash -LiteralPath $setup -Algorithm SHA256).Hash;$msiHash=(Get-FileHash -LiteralPath $msi -Algorithm SHA256).Hash
$sig=Get-AuthenticodeSignature -LiteralPath $setup;if($AllowSigned){if($sig.Status-notin @([Management.Automation.SignatureStatus]::Valid,[Management.Automation.SignatureStatus]::NotSigned)){throw "Setup signature invalid: $($sig.Status)."}}elseif($sig.Status-ne[Management.Automation.SignatureStatus]::NotSigned){throw 'Use -AllowSigned only for a valid signed Setup.'}
$fs=[IO.File]::OpenRead($setup);try{$br=New-Object IO.BinaryReader($fs);if($br.ReadUInt16()-ne0x5A4D){throw 'Setup is not PE.'};$fs.Position=0x3C;$off=$br.ReadInt32();if($off-lt64-or$off+6-gt$fs.Length){throw 'Invalid PE header.'};$fs.Position=$off;if($br.ReadUInt32()-ne0x4550){throw 'Invalid PE signature.'};Eq $br.ReadUInt16() 0x8664 'Setup PE machine'}finally{$fs.Dispose()}
$wix=Join-Path $env:USERPROFILE '.nuget\packages\wixtoolset.sdk\4.0.6\tools\net472\x64\wix.exe';if(-not(Test-Path -LiteralPath $wix -PathType Leaf)){throw "Pinned WiX missing: $wix"}
if(-not(Test-Path -LiteralPath $verifyRoot)){New-Item -ItemType Directory -Path $verifyRoot|Out-Null};if(((Get-Item -LiteralPath $verifyRoot).Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw 'Verification root is a reparse point.'}
$tmp=SafeTemp (Join-Path $verifyRoot ('standalone-setup-static-'+[guid]::NewGuid().ToString('N')));$payload=Join-Path $tmp 'payloads';$ba=Join-Path $tmp 'ba';New-Item -ItemType Directory -Path $tmp|Out-Null
try{
 & $wix burn extract $setup -o $payload -oba $ba|Out-Host;if($LASTEXITCODE-ne0){throw "Burn extraction failed: $LASTEXITCODE"}
 $mp=Join-Path $ba 'manifest.xml';$bp=Join-Path $ba 'BootstrapperApplicationData.xml';$ep=Join-Path $ba 'BundleExtensionData.xml';foreach($f in $mp,$bp,$ep){if(-not(Test-Path -LiteralPath $f -PathType Leaf)){throw "Burn metadata missing: $f"}}
 $man=XML $mp;$bad=XML $bp;$ext=XML $ep;$burn=$man.DocumentElement;Eq $burn.LocalName 'BurnManifest' 'Burn root';Eq $burn.GetAttribute('Win64') 'yes' 'Burn Win64'
 $rel=One @($burn.SelectNodes("./*[local-name()='RelatedBundle']")|?{$_.GetAttribute('Action')-eq'Upgrade'}) 'Bundle UpgradeCode';EqI $rel.GetAttribute('Id') $bundleCode 'Bundle UpgradeCode'
 $reg=One @($burn.SelectNodes("./*[local-name()='Registration']")) 'Bundle registration';Eq $reg.GetAttribute('Version') $ProductVersion 'Bundle version'
 $chain=One @($burn.SelectNodes("./*[local-name()='Chain']")) 'Bundle chain';$pk=@($chain.ChildNodes|?{$_.NodeType-eq[Xml.XmlNodeType]::Element});Eq $pk.Count 3 'Chain count';$ids=@($pk|%{$_.GetAttribute('Id')});foreach($id in 'DotNetDesktopRuntime10x64','WebView2RuntimeX64','AutoCardSyncMsi'){if(@($ids|?{$_-eq$id}).Count-ne1){throw "Chain package missing/unexpected: $id"}}
 $rp=One @($pk|?{$_.GetAttribute('Id')-eq'DotNetDesktopRuntime10x64'}) 'Runtime package';$wp=One @($pk|?{$_.GetAttribute('Id')-eq'WebView2RuntimeX64'}) 'WebView2 package';$ip=One @($pk|?{$_.GetAttribute('Id')-eq'AutoCardSyncMsi'}) 'MSI package';Eq $rp.LocalName 'ExePackage' 'Runtime type';Eq $wp.LocalName 'ExePackage' 'WebView2 type';Eq $ip.LocalName 'MsiPackage' 'MSI type';Eq $wp.GetAttribute('DetectCondition') 'WebView2RuntimeMachineVersion OR WebView2RuntimeUserVersion' 'WebView2 condition';Eq $ip.GetAttribute('PerMachine') 'no' 'MSI scope';Eq $ip.GetAttribute('Permanent') 'no' 'MSI permanence';$visibility=$ip.GetAttribute('Visible');if($visibility-notin @('','no')){throw "MSI visibility mismatch: expected default/no, actual '$visibility'."};Eq $ip.GetAttribute('Version') $ProductVersion 'MSI chain version';EqI $ip.GetAttribute('UpgradeCode') $msiCode 'MSI chain UpgradeCode'
 $bind=One @($ip.ChildNodes|?{$_.LocalName-eq'MsiProperty'-and($_.GetAttribute('Id')-eq'CREATE_DESKTOP_SHORTCUT'-or$_.GetAttribute('Name')-eq'CREATE_DESKTOP_SHORTCUT')}) 'Desktop MSI binding';Eq $bind.GetAttribute('Value') '[CreateDesktopShortcut]' 'Desktop MSI binding value'
 $pl=@($burn.ChildNodes|?{$_.LocalName-eq'Payload'});$rpl=One @($pl|?{$_.GetAttribute('Id')-eq'DotNetDesktopRuntime10x64'}) 'Runtime payload';$wpl=One @($pl|?{$_.GetAttribute('Id')-eq'WebView2RuntimeX64'}) 'WebView2 payload';$ipl=One @($pl|?{$_.GetAttribute('FilePath')-eq'AutoCardSync-Standalone.msi'}) 'MSI payload';foreach($x in @(@($rpl,$rm,'Runtime'),@($wpl,$wm,'WebView2'))){Eq $x[0].GetAttribute('Packaging') 'embedded' "$($x[2]) packaging";Eq $x[0].GetAttribute('FilePath') $x[1].File "$($x[2]) filename";Eq $x[0].GetAttribute('FileSize') ([string]$x[1].Size) "$($x[2]) size";Eq $x[0].GetAttribute('Hash') $x[1].Hash "$($x[2]) hash"};Eq $ipl.GetAttribute('Packaging') 'embedded' 'MSI packaging'
 $all=$man.OuterXml+$bad.OuterXml+$ext.OuterXml;foreach($n in @(@('WebView2RuntimeMachineSearch','WebView2RuntimeMachineVersion','Root="(2|HKLM|Machine)"'),@('WebView2RuntimeUserSearch','WebView2RuntimeUserVersion','Root="(1|HKCU|User)"'))){if($all-notmatch[regex]::Escape($n[0])-or$all-notmatch[regex]::Escape($n[1])-or$all-notmatch[regex]::Escape($wvKey)-or$all-notmatch$n[2]){throw "Invalid WebView2 search $($n[0])."}};$codes=@([regex]::Matches($all,'(?i)EdgeUpdate\\Clients\\(\{[0-9A-F-]{36}\})')|%{$_.Groups[1].Value}|select -Unique);if($codes.Count-ne1-or-not[string]::Equals($codes[0],$wvCode,[StringComparison]::OrdinalIgnoreCase)){throw 'WebView2 detection uses wrong product GUID.'}
 $launchVariable=One @($burn.SelectNodes("./*[local-name()='Variable']")|?{$_.GetAttribute('Id')-eq'LaunchTarget'}) 'LaunchTarget variable';$lt=$launchVariable.GetAttribute('Value');if($lt-notmatch'(?i)(^|[\\/])AutoCardSync\.Standalone\.exe$'){throw "Invalid LaunchTarget: $lt"};$launchFolder=One @($burn.SelectNodes("./*[local-name()='Variable']")|?{$_.GetAttribute('Id')-eq'LaunchWorkingFolder'}) 'LaunchWorkingFolder variable';Eq $launchFolder.GetAttribute('Value') '[LocalAppDataFolder]Programs\AutoCardSync' 'LaunchWorkingFolder'
 $attached=Join-Path $payload 'WixAttachedContainer';$er=Join-Path $attached $rm.File;$ew=Join-Path $attached $wm.File;$em=Join-Path $attached 'AutoCardSync-Standalone.msi';foreach($f in $er,$ew,$em){if(-not(Test-Path -LiteralPath $f -PathType Leaf)){throw "Extracted payload missing: $f"}};Eq (Get-Item $er).Length $rm.Size 'Runtime extracted size';Eq (Get-FileHash $er -Algorithm SHA512).Hash $rm.Hash 'Runtime extracted hash';$rs=MicrosoftSig $er $rm 'Runtime';Eq (Get-Item $ew).Length $wm.Size 'WebView2 extracted size';Eq (Get-FileHash $ew -Algorithm SHA512).Hash $wm.Hash 'WebView2 extracted hash';$ws=MicrosoftSig $ew $wm 'WebView2';$embeddedHash=(Get-FileHash $em -Algorithm SHA256).Hash;Eq $embeddedHash $msiHash 'Embedded MSI SHA-256'
 $wi=New-Object -ComObject WindowsInstaller.Installer;$db=$wi.OpenDatabase($em,0);try{$q=[char]96;Eq (Prop $db 'ProductVersion') $ProductVersion 'MSI ProductVersion';EqI (Prop $db 'UpgradeCode') $msiCode 'MSI UpgradeCode';if(Prop $db 'ALLUSERS'){throw 'MSI is not per-user.'};if((Prop $db 'ARPSYSTEMCOMPONENT')-eq'1'-or(Prop $db 'ARPNOREMOVE')-eq'1'){throw 'Normal uninstall is disabled.'};foreach($t in 'ServiceInstall','ServiceControl'){if(HasTable $db $t){throw "Forbidden MSI table: $t"}};$files=@(Rows $db "SELECT ${q}Component_${q},${q}FileName${q} FROM ${q}File${q}" 2);if(@($files|?{(LongName $_[1])-eq'AutoCardSync.Standalone.exe'}).Count-ne1){throw 'Standalone EXE missing.'};if(@($files|?{(LongName $_[1])-match'(?i)AutoCardSync\.(Agent\.(Service|Tray)|Dashboard|CaSigner|AdminCli)(\.|$)'}).Count){throw 'V2 file found in Standalone MSI.'};Eq (Prop $db 'ARPPRODUCTICON') 'AutoCardSync.ico' 'ARP product icon';if(-not(HasTable $db 'Icon')){throw 'MSI Icon table missing.'};if(@(Rows $db "SELECT ${q}Name${q} FROM ${q}Icon${q} WHERE ${q}Name${q} = 'AutoCardSync.ico'" 1).Count-ne1){throw 'MSI product icon payload missing.'};$short=@(Rows $db "SELECT ${q}Directory_${q},${q}Name${q},${q}Component_${q},${q}Target${q},${q}Icon_${q} FROM ${q}Shortcut${q}" 5);$start=One @($short|?{$_[0]-eq'ApplicationProgramsFolder'-and(LongName $_[1])-eq'AutoCardSync'-and$_[3]-eq'[INSTALLFOLDER]AutoCardSync.Standalone.exe'}) 'Start menu shortcut';$desk=One @($short|?{$_[0]-eq'DesktopFolder'-and(LongName $_[1])-eq'AutoCardSync'-and$_[3]-eq'[INSTALLFOLDER]AutoCardSync.Standalone.exe'}) 'Desktop shortcut';Eq $start[4] 'AutoCardSync.ico' 'Start menu shortcut icon';Eq $desk[4] 'AutoCardSync.ico' 'Desktop shortcut icon';$comp=@(Rows $db "SELECT ${q}Component${q},${q}Condition${q},${q}Attributes${q} FROM ${q}Component${q}" 3);$dc=One @($comp|?{$_[0]-eq$desk[2]}) 'Desktop component';Eq (([string]$dc[1])-replace'\s+','') 'CREATE_DESKTOP_SHORTCUT=1' 'Desktop condition';if(@($comp|?{(([int]$_[2])-band16)-ne0}).Count){throw 'Permanent MSI component prevents normal uninstall.'};$rr=@(Rows $db "SELECT ${q}Root${q},${q}Key${q},${q}Name${q},${q}Value${q} FROM ${q}Registry${q}" 4);$runCount=@($rr|?{$_[0]-eq'1'-and$_[1]-eq'Software\Microsoft\Windows\CurrentVersion\Run'-and$_[2]-eq'AutoCardSync'}).Count;if($runCount-ne0){throw 'MSI must not own a permanent HKCU Run value.'};$exeRows=@(Rows $db "SELECT ${q}File${q},${q}FileName${q} FROM ${q}File${q}" 2);$exeFile=One @($exeRows|?{(LongName $_[1])-eq'AutoCardSync.Standalone.exe'}) 'Standalone EXE file key';$ca=@(Rows $db "SELECT ${q}Action${q},${q}Type${q},${q}Source${q},${q}Target${q} FROM ${q}CustomAction${q}" 4);$reconcile=One @($ca|?{$_[0]-eq'ReconcileAutoStart'}) 'Auto-start reconciliation action';Eq $reconcile[2] $exeFile[0] 'Auto-start reconciliation EXE';Eq $reconcile[3] '--reconcile-autostart' 'Auto-start reconciliation command';$remove=One @($ca|?{$_[0]-eq'RemoveAutoStart'}) 'Auto-start removal action';Eq $remove[2] $exeFile[0] 'Auto-start removal EXE';Eq $remove[3] '--remove-autostart' 'Auto-start removal command';$seq=@(Rows $db "SELECT ${q}Action${q},${q}Condition${q},${q}Sequence${q} FROM ${q}InstallExecuteSequence${q}" 3);$reconcileSeq=One @($seq|?{$_[0]-eq'ReconcileAutoStart'}) 'Auto-start reconciliation sequence';Eq (([string]$reconcileSeq[1])-replace'\s+','') 'NOT(REMOVE~="ALL")' 'Auto-start reconciliation condition';$removeSeq=One @($seq|?{$_[0]-eq'RemoveAutoStart'}) 'Auto-start removal sequence';Eq (([string]$removeSeq[1])-replace'\s+','') 'REMOVE~="ALL"ANDNOTUPGRADINGPRODUCTCODE' 'Auto-start removal condition';$up=@(Rows $db "SELECT ${q}UpgradeCode${q},${q}ActionProperty${q} FROM ${q}Upgrade${q}" 2);foreach($ap in 'WIX_UPGRADE_DETECTED','WIX_DOWNGRADE_DETECTED'){if(@($up|?{[string]::Equals($_[0],$msiCode,[StringComparison]::OrdinalIgnoreCase)-and$_[1]-eq$ap}).Count-ne1){throw "MSI upgrade/uninstall relation missing: $ap"}}}finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($db);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wi)}
 Eq (Get-FileHash $setup -Algorithm SHA256).Hash $setupHash 'Setup continuity';Eq (Get-FileHash $msi -Algorithm SHA256).Hash $msiHash 'MSI continuity'
 $result=[ordered]@{schemaVersion=1;sourceCommit=$head.ToLowerInvariant();setupPath=$SetupPath;setupVersion=$SetupVersion;productVersion=$ProductVersion;setupSha256=$setupHash;peMachine='x64';bundleUpgradeCode=$bundleCode;chainPackages=$ids;internalMsiSha256=$msiHash;embeddedMsiSha256=$embeddedHash;msiUpgradeCode=$msiCode;launchTarget=$lt;autoStartPreferenceOwner='application-configuration';msiOwnsPermanentRunValue=$false;msiRunValueCount=$runCount;reconciliationEntryPoint='--reconcile-autostart';uninstallRemovesDerivedRunValue=$true;webView2ProductCode=$wvCode;runtimeSha512=$rm.Hash;runtimeSigner=$rs;webView2Sha512=$wm.Hash;webView2Signer=$ws;checks='PASS';builtInstaller=$false;executedInstaller=$false};New-Item -ItemType Directory -Path (Split-Path -Parent $evidence) -Force|Out-Null;[IO.File]::WriteAllText($evidence,($result|ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false));$result|ConvertTo-Json -Depth 6
}finally{if(Test-Path -LiteralPath $tmp -PathType Container){$safe=SafeTemp $tmp;$it=Get-Item -LiteralPath $safe;if(($it.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw "Refusing to delete reparse point: $safe"};Remove-Item -LiteralPath $safe -Recurse -Force}}
